// ═══ WAY 1: Extend Thread — NOT recommended ═══
class TradeProcessor extends Thread {
    @Override
    public void run() {
        System.out.println("Processing trade on: " + Thread.currentThread().getName());
    }
}
TradeProcessor tp = new TradeProcessor();
tp.start();  // creates new OS thread, calls run()
// Problem: TradeProcessor can't extend any other class (single inheritance!)
// Problem: task (processing) is coupled to threading mechanism

// ═══ WAY 2: Implement Runnable — GOOD ═══
class TradeTask implements Runnable {
    private final String tradeId;
    TradeTask(String tradeId) { this.tradeId = tradeId; }

    @Override
    public void run() {
        System.out.println("Processing: " + tradeId);
        // No return value. Can't throw checked exceptions.
    }
}
Thread t = new Thread(new TradeTask("TRD-001"));
t.start();  // or use ExecutorService!

// Lambda (Java 8):
new Thread(() -> System.out.println("Processing trade")).start();

// ═══ WAY 3: Callable + ExecutorService — BEST ═══
class TradeSettler implements Callable<String> {
    private final String tradeId;
    TradeSettler(String tradeId) { this.tradeId = tradeId; }

    @Override
    public String call() throws Exception {  // returns result + throws checked exceptions!
        Thread.sleep(100);  // simulate work
        return "SETTLED:" + tradeId;
    }
}
ExecutorService pool = Executors.newFixedThreadPool(10);
Future<String> future = pool.submit(new TradeSettler("TRD-001"));
String result = future.get();  // blocks until result ready → "SETTLED:TRD-001"
pool.shutdown();

// ═══ WHY ExecutorService (thread pool) is MANDATORY in production ═══
// Raw threads: new Thread().start() for each request
//   10K requests → 10K threads → 10GB stack memory → OOM!
//   No limit, no reuse, no monitoring.
// Thread pool: ExecutorService with fixed size (e.g., 200 threads)
//   10K requests → queued → 200 threads process them → reused → efficient!
//   Limit concurrency, reuse threads, handle rejection, monitor metrics.

// ═══ COMPARISON TABLE ═══
// Feature              Thread          Runnable          Callable+Executor
// Return value         No              No                Yes (Future<V>)
// Checked exceptions   No              No                Yes (call() throws)
// Inheritance          extends Thread  implements iface  implements iface
// Thread pool          No              Yes               Yes
// Production-ready     No              Better            BEST
