package com.bank.threads;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.ArrayList;
import java.util.List;
import static org.assertj.core.api.Assertions.*;

class ThreadCreationTest {

    // ═══ WAY 1: Extend Thread ═══
    static class TradeThread extends Thread {
        String result;
        @Override
        public void run() {
            result = "Processed on " + getName();
        }
    }

    @Test
    void extendThread() throws InterruptedException {
        TradeThread t = new TradeThread();
        t.start();
        t.join();
        assertThat(t.result).startsWith("Processed on");
    }

    // ═══ WAY 2: Implement Runnable ═══
    @Test
    void implementRunnable() throws InterruptedException {
        String[] result = {null};
        Runnable task = () -> result[0] = "Trade settled";
        Thread t = new Thread(task);
        t.start();
        t.join();
        assertThat(result[0]).isEqualTo("Trade settled");
    }

    // ═══ WAY 3: Callable + ExecutorService — BEST ═══
    @Test
    void callableWithExecutor() throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(4);

        Callable<String> settler = () -> {
            Thread.sleep(50);
            return "SETTLED:TRD-001";
        };

        Future<String> future = pool.submit(settler);
        assertThat(future.isDone()).isFalse();  // still processing!

        String result = future.get(5, TimeUnit.SECONDS);  // block until done
        assertThat(result).isEqualTo("SETTLED:TRD-001");
        assertThat(future.isDone()).isTrue();

        pool.shutdown();
    }

    // ═══ Multiple Callables — process batch ═══
    @Test
    void batchProcessing() throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(4);
        List<Future<String>> futures = new ArrayList<>();

        for (int i = 1; i <= 10; i++) {
            final int tradeNum = i;
            futures.add(pool.submit(() -> "SETTLED:TRD-" + String.format("%03d", tradeNum)));
        }

        List<String> results = new ArrayList<>();
        for (Future<String> f : futures) {
            results.add(f.get(5, TimeUnit.SECONDS));
        }

        assertThat(results).hasSize(10);
        assertThat(results).allMatch(r -> r.startsWith("SETTLED:"));

        pool.shutdown();
    }

    // ═══ Runnable vs Callable comparison ═══
    @Test
    void runnableHasNoReturn_callableHas() throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(2);

        // Runnable: no return value
        Future<?> runnableFuture = pool.submit((Runnable) () -> {
            /* process trade — no return */
        });
        assertThat(runnableFuture.get()).isNull();  // always null!

        // Callable: has return value
        Future<String> callableFuture = pool.submit(() -> "SETTLED");
        assertThat(callableFuture.get()).isEqualTo("SETTLED");  // actual result!

        pool.shutdown();
    }
}
